class DeviceDetector{constructor(){this.deviceType=null,this.userAgent=navigator.userAgent,this.screenWidth=window.screen.width,this.screenHeight=window.screen.height}detectDevice(){const e=this.isMobileUserAgent(),i=this.isMobileScreen(),t=this.isMobileTouch();return this.deviceType=e||i||t?"mobile":"desktop",this.deviceType}isMobileUserAgent(){return["Android","iPhone","iPad","iPod","BlackBerry","Windows Phone","Mobile","Opera Mini","IEMobile"].some(e=>this.userAgent.includes(e))}isMobileScreen(){return this.screenWidth<768||this.screenHeight<768}isMobileTouch(){return"ontouchstart"in window||navigator.maxTouchPoints>0||navigator.msMaxTouchPoints>0}getDeviceInfo(){return{type:this.deviceType,userAgent:this.userAgent,screenWidth:this.screenWidth,screenHeight:this.screenHeight,isTouch:this.isMobileTouch(),platform:navigator.platform,language:navigator.language}}isTablet(){return["iPad","Android.*Tablet"].some(e=>new RegExp(e,"i").test(this.userAgent))}getOrientation(){return this.screenWidth>this.screenHeight?"landscape":"portrait"}}